uid_t target_uid = 1001;
int status;

// Set EID to 0 (root), RUID unchanged
// Requires capability or current EID=0/RUID=0/SavedUID=0
status = setreuid32((uid_t)-1, 0);

// Drop privileges: Set both RUID and EID to target_uid
if (status == 0) {
    status = setreuid32(target_uid, target_uid);
}

// Restore saved privileges (EID back to 0), RUID unchanged
if (status == 0) {
    status = setreuid32((uid_t)-1, 0);
}

if (status == -1) {
    /* Handle EAGAIN (resource limits) or EINVAL (invalid IDs) */
    perror("setreuid32 failure");
}
